const crypto = require('crypto');

// 1. Capturar os dados binários do HTTP Request
const binaryData = await this.helpers.getBinaryDataBuffer(0, 'data');

// 2. Capturar o mediaKey (Ajustado para o caminho confirmado em suas imagens)
const webhookData = $('Webhook').first().json.body;
const mediaKeyBase64 = webhookData.message.audioMessage.mediaKey;
const mediaKey = Buffer.from(mediaKeyBase64, 'base64');

// 3. Derivação de chaves HKDF
const info = "WhatsApp Audio Keys";
const salt = Buffer.alloc(32); 
const expanded = crypto.hkdfSync('sha256', mediaKey, salt, info, 112);

const iv = expanded.slice(0, 16);
const cipherKey = expanded.slice(16, 48);

// 4. Descriptografia sem finalizar (Para evitar erro de state)
const decipher = crypto.createDecipheriv('aes-256-cbc', cipherKey, iv);
decipher.setAutoPadding(false);

// IMPORTANTE: Pegamos apenas o update para evitar o erro de unsupported state
const decrypted = decipher.update(binaryData);

// 5. Saída binária para o n8n
return {
  json: { 
    resultado: "Sucesso", 
    tamanho_bytes: decrypted.length 
  },
  binary: {
    data: await this.helpers.prepareBinaryData(decrypted, 'audio.ogg', 'audio/ogg')
  }
};
